      c.fillStyle = "rgba(9, 9, 11, 0.92)";
      c.strokeStyle = "#d97706";
      c.lineWidth = 1.2;
      c.beginPath();
      c.roundRect(bx, by, tw, 13, 4);
      c.fill();
      c.stroke();

