    // ENTRADA DA ESCADARIA NA SUPERFÍCIE (Poço de Mármore que DESCE ao Subsolo)
    // =========================================================================
    // 1. Sombra projetada ao redor do poço da escadaria
    e.fillStyle = "rgba(2, 6, 23, 0.45)";
