    e.fillRect(-1.5 * t, -3.5 * t, 1 * t, 1 * t);
    e.fillRect(0.5 * t, -3.5 * t, 1 * t, 1 * t);

    // Costelas e ossos caídos
    e.strokeStyle = "#94a3b8";
