        skyGrad.addColorStop(0, "#030712");
        skyGrad.addColorStop(0.35, "#0b0f19");
        skyGrad.addColorStop(0.65, "#15162c");
        skyGrad.addColorStop(0.85, "#1e1b4b");
        skyGrad.addColorStop(1, "#090d16");
