        moonGlow.addColorStop(0.4, "rgba(99, 102, 241, 0.04)");
        moonGlow.addColorStop(1, "rgba(0, 0, 0, 0)");
        ctx.fillStyle = moonGlow;
        ctx.fillRect(0, 0, width, height);

