        ctx.fillStyle = "#0c1122";
        ctx.beginPath();
        ctx.moveTo(0, height * 0.72);
        ctx.lineTo(width * 0.18, height * 0.52);
        ctx.lineTo(width * 0.38, height * 0.64);
        ctx.lineTo(width * 0.62, height * 0.46);
